const uid=()=>crypto.randomUUID?crypto.randomUUID():"xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==="x"?r:(r&3|8)).toString(16)});
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function showAuthMessage(msg,error=false){const el=document.getElementById("authMessage");el.textContent=msg||"";el.classList.toggle("error",error)}
function setAuthMode(mode){authMode=mode;const signup=mode==="signup";document.getElementById("authTitle").textContent=signup?"Crie sua conta":"Entre na sua conta";document.getElementById("authCopy").textContent=signup?"Cadastre-se para guardar seus treinos na nuvem.":"Acesse suas fichas e mantenha seus treinos salvos na nuvem.";document.getElementById("authNameField").classList.toggle("hidden",!signup);document.getElementById("authName").required=signup;document.getElementById("authSubmit").textContent=signup?"Criar conta":"Entrar";document.getElementById("authSwitch").textContent=signup?"Já tem conta? Entrar":"Ainda não tem conta? Criar cadastro";document.getElementById("authPassword").autocomplete=signup?"new-password":"current-password";showAuthMessage("")}
document.getElementById("authSwitch").addEventListener("click",()=>setAuthMode(authMode==="login"?"signup":"login"));
function withTimeout(promise,ms,message){let timer;return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(message)),ms)})]).finally(()=>clearTimeout(timer))}
function authErrorMessage(err){const msg=String(err?.message||"");if(/invalid login credentials/i.test(msg))return "E-mail ou senha incorretos. Confira os dados ou crie uma conta.";if(/email not confirmed/i.test(msg))return "Confirme seu e-mail pelo link enviado antes de entrar.";if(/user already registered/i.test(msg))return "Este e-mail já tem cadastro. Entre na sua conta.";if(/password should be at least|password.*6 characters/i.test(msg))return "A senha precisa ter pelo menos 6 caracteres.";if(/rate limit|too many requests/i.test(msg))return "Muitas tentativas em pouco tempo. Aguarde um pouco e tente novamente.";if(/failed to fetch|network|fetch/i.test(msg))return "Falha de conexão. Verifique a internet e tente novamente.";return msg||"Não foi possível autenticar. Tente novamente."}
document.getElementById("authForm").addEventListener("submit",async e=>{e.preventDefault();const btn=document.getElementById("authSubmit");if(btn.disabled)return;const mode=authMode,email=document.getElementById("authEmail").value.trim(),password=document.getElementById("authPassword").value,name=document.getElementById("authName").value.trim();if(!email||!password||(mode==="signup"&&!name)){showAuthMessage("Preencha todos os campos obrigatórios.",true);return}btn.disabled=true;btn.setAttribute("aria-busy","true");btn.textContent=mode==="signup"?"Criando conta…":"Entrando…";showAuthMessage(mode==="signup"?"Criando sua conta…":"Validando seus dados…");try{if(mode==="signup"){const {data:r,error}=await withTimeout(supabaseClient.auth.signUp({email,password,options:{data:{full_name:name}}}),15000,"A autenticação demorou demais. Verifique sua conexão e tente novamente.");if(error)throw error;if(r.session?.user){await withTimeout(activateSession(r.session.user),15000,"Sua conta foi autenticada, mas o carregamento demorou. Atualize a página para continuar.")}else{showAuthMessage("Cadastro criado. Confira sua caixa de entrada e o spam para confirmar o e-mail; depois, entre com sua senha.")}}else{const {data:r,error}=await withTimeout(supabaseClient.auth.signInWithPassword({email,password}),15000,"A autenticação demorou demais. Verifique sua conexão e tente novamente.");if(error)throw error;if(!r.user)throw new Error("O serviço não retornou uma conta válida. Tente novamente.");await withTimeout(activateSession(r.user),15000,"Login validado, mas o carregamento dos treinos demorou. Atualize a página para continuar.")}}catch(err){console.error("Falha na autenticação:",err);showAuthMessage(authErrorMessage(err),true)}finally{btn.disabled=false;btn.removeAttribute("aria-busy");btn.textContent=mode==="signup"?"Criar conta":"Entrar"} });
async function activateSession(user){currentUser=user;try{const {data:rows,error}=await withTimeout(supabaseClient.from("workouts").select("id,name,category,exercises,created_at").eq("user_id",user.id).order("updated_at",{ascending:false}),12000,"O login foi feito, mas a lista de treinos não respondeu. Atualize a página ou tente novamente.");if(error)throw error;let history=[];try{history=JSON.parse(localStorage.getItem(historyKey())||"[]");if(!Array.isArray(history))history=[]}catch{}data={workouts:(rows||[]).map(r=>({id:r.id,name:r.name,focus:r.category,exercises:Array.isArray(r.exercises)?r.exercises:[],createdAt:r.created_at})),history};document.getElementById("authScreen").classList.add("hidden");document.getElementById("appRoot").classList.remove("auth-locked");const display=user.user_metadata?.full_name||user.email||"Minha conta";document.getElementById("profileEmail").textContent=user.email||"";document.getElementById("profileAvatar").textContent=display.trim().charAt(0).toUpperCase()||"HF";try{preferences={...preferences,...JSON.parse(localStorage.getItem(preferencesKey())||"{}")}}catch{}if(!preferences.name)preferences.name=user.user_metadata?.full_name||"";applyPreferences();fillSettings();renderHome();renderWorkouts();renderHistory();renderProfile();refreshShareOptions();document.getElementById("createPostFab")?.classList.remove("hidden");loadFeedPosts()}catch(err){currentUser=null;showAuthMessage("Não foi possível carregar seus treinos: "+(err.message||"erro desconhecido"),true);throw err}}
supabaseClient.auth.onAuthStateChange((event,session)=>{if(event==="SIGNED_OUT"){currentUser=null;data={workouts:[],history:[]};document.getElementById("appRoot").classList.add("auth-locked");document.getElementById("authScreen").classList.remove("hidden")}});
(async()=>{const {data:{session},error}=await supabaseClient.auth.getSession();if(error)showAuthMessage(error.message,true);else if(session?.user){try{await activateSession(session.user)}catch(err){console.error(err)}}})();
document.getElementById("signOutButton").addEventListener("click",async()=>{if(activeSession&&!confirm("Há um treino em andamento. Deseja sair mesmo assim?"))return;activeSession=null;await supabaseClient.auth.signOut();document.getElementById("authForm").reset();setAuthMode("login")});
async function saveData(){
 if(!currentUser){alert("Entre na sua conta para salvar seus treinos.");return false}
 const userId=currentUser.id;
 try{localStorage.setItem(historyKey(),JSON.stringify(data.history))}catch(err){console.error(err)}
 saveQueue=saveQueue.then(async()=>{
  if(!currentUser||currentUser.id!==userId)throw new Error("Sua sessão mudou. Entre novamente e tente salvar.");
  const payload=data.workouts.map(w=>({id:w.id,user_id:userId,name:w.name,category:w.focus||"Personalizado",exercises:w.exercises||[],updated_at:new Date().toISOString()}));
  if(payload.length){const {error}=await supabaseClient.from("workouts").upsert(payload,{onConflict:"id"});if(error)throw error}
  const {data:rows,error}=await supabaseClient.from("workouts").select("id").eq("user_id",userId);if(error)throw error;
  const keep=new Set(data.workouts.map(w=>w.id)),remove=(rows||[]).map(r=>r.id).filter(id=>!keep.has(id));
  if(remove.length){const {error}=await supabaseClient.from("workouts").delete().eq("user_id",userId).in("id",remove);if(error)throw error}
  return true;
 }).catch(err=>{console.error(err);alert("Não foi possível salvar na nuvem: "+(err.message||"tente novamente"));return false});
 return await saveQueue;
}
function getWorkout(id){return data.workouts.find(w=>w.id===id)}
function setView(view){if(activeSession&&view!=="session"){alert("Finalize ou cancele a sessão antes de sair do treino.");return}document.querySelectorAll(".content > section").forEach(el=>el.classList.add("hidden"));document.getElementById("view-"+view)?.classList.remove("hidden");document.querySelectorAll(".nav-btn").forEach(b=>b.classList.toggle("active",b.dataset.view===view));document.getElementById("createPostFab")?.classList.toggle("hidden",view!=="home");document.getElementById("topbarTitle").textContent=({home:"Feed",workouts:"Rotina",exercise:"Exercício",training:"Treinar",profile:"Perfil",settings:"Configurações",history:"Histórico",session:"Treino em andamento"})[view]||"Hyfolium";if(view==="home"){renderHome();if(typeof loadFeedPosts==="function")loadFeedPosts()}if(view==="workouts")renderWorkouts();if(view==="history")renderHistory();if(view==="session")renderSession();if(view==="profile"&&typeof renderProfile==="function")renderProfile();if(view==="training"&&typeof refreshShareOptions==="function")refreshShareOptions();if(view==="settings"&&typeof fillSettings==="function")fillSettings()}
document.querySelectorAll(".nav-btn").forEach(b=>b.addEventListener("click",()=>setView(b.dataset.view)));
function emptyHTML(icon,title,message){return `<div class="empty"><div class="empty-icon">${icon}</div><h3>${esc(title)}</h3><p>${esc(message)}</p></div>`}
function workoutCardHTML(w){return `<article class="workout-card"><div class="workout-top"><div class="workout-letter">${esc(w.name.charAt(0).toUpperCase())}</div><span class="pill">${w.exercises.length} exercício(s)</span></div><h3>${esc(w.name)}</h3><p>${esc(w.focus)}</p><div class="card-actions"><button class="btn btn-primary btn-small" onclick="openWorkout('${w.id}')">Abrir ficha</button><button class="btn btn-outline btn-small" onclick="editWorkout('${w.id}')">Editar</button><button class="btn btn-danger btn-small" onclick="deleteWorkout('${w.id}')">Excluir</button></div></article>`}
function renderHome(){document.getElementById("statWorkouts").textContent=data.workouts.length;document.getElementById("statSessions").textContent=data.history.length;document.getElementById("statExercises").textContent=data.workouts.reduce((n,w)=>n+w.exercises.length,0);document.getElementById("homeWorkouts").innerHTML=data.workouts.length?`<div class="workout-grid">${data.workouts.slice(0,4).map(workoutCardHTML).join("")}</div>`:emptyHTML("▤","Você ainda não tem fichas","Crie seu primeiro treino e adicione exercícios.");document.getElementById("homeHistory").innerHTML=data.history.length?data.history.slice(0,3).map(historyHTML).join(""):'<p class="subtitle">Suas sessões concluídas aparecerão aqui.</p>'}
function showCreateForm(){setView("exercise");editingWorkoutId=null;document.getElementById("formTitle").textContent="Criar ficha de treino";document.getElementById("workoutForm").reset();document.getElementById("createForm").classList.remove("hidden");document.getElementById("workoutName").focus()}
function hideCreateForm(){document.getElementById("createForm").classList.add("hidden");editingWorkoutId=null}
document.getElementById("workoutForm").addEventListener("submit",async e=>{
 e.preventDefault();
 const name=document.getElementById("workoutName").value.trim(),focus=document.getElementById("workoutFocus").value;
 if(!name){alert("Dê um nome para a ficha.");return}
 const wasEditing=Boolean(editingWorkoutId),w=wasEditing?getWorkout(editingWorkoutId):null;
 if(wasEditing&&!w){alert("Não encontrei essa ficha. Atualize a página e tente novamente.");return}
 const previous=w?{...w,exercises:[...w.exercises]}:null;
 let newId=editingWorkoutId;
 if(w){w.name=name;w.focus=focus}
 else{const created={id:uid(),name,focus,exercises:[],createdAt:new Date().toISOString()};data.workouts.push(created);newId=created.id}
 const button=e.submitter;if(button){button.disabled=true;button.textContent="Salvando..."}
 const saved=await saveData();
 if(button){button.disabled=false;button.textContent="Salvar ficha"}
 if(!saved){if(w&&previous)Object.assign(w,previous);else data.workouts=data.workouts.filter(x=>x.id!==newId);return}
 hideCreateForm();renderWorkouts();renderHome();refreshShareOptions();setView("workouts");if(newId)openWorkout(newId);
});
function editWorkout(id){const w=getWorkout(id);if(!w)return;editingWorkoutId=id;setView("exercise");document.getElementById("createForm").classList.remove("hidden");document.getElementById("formTitle").textContent="Editar ficha";document.getElementById("workoutName").value=w.name;document.getElementById("workoutFocus").value=w.focus}
async function deleteWorkout(id){
 const w=getWorkout(id);if(!w||!confirm(`Excluir a ficha "${w.name}"? Essa ação não pode ser desfeita.`))return;
 const buttons=[...document.querySelectorAll(`button[onclick="deleteWorkout('${id}')"]`)];
 buttons.forEach(b=>{b.disabled=true;b.textContent="Excluindo..."}); 
 try{
  saveQueue=saveQueue.catch(()=>{}).then(async()=>{
   if(!currentUser)throw new Error("Sua sessão expirou. Entre novamente.");
   const {data:deleted,error}=await supabaseClient.from("workouts").delete().eq("id",id).eq("user_id",currentUser.id).select("id");
   if(error)throw error;
   if(!deleted?.length)throw new Error("O banco não confirmou a exclusão. Verifique as permissões da tabela workouts.");
  });
  await saveQueue;
  data.workouts=data.workouts.filter(item=>item.id!==id);
  if(selectedWorkoutId===id){selectedWorkoutId=null;document.getElementById("workoutDetail").classList.add("hidden");document.getElementById("workoutGrid").classList.remove("hidden")}
  if(editingWorkoutId===id)hideCreateForm();
  renderWorkouts();renderHome();refreshShareOptions();
 }catch(err){console.error("Erro ao excluir ficha:",err);alert("Não foi possível excluir a ficha: "+(err.message||"tente novamente"))}
 finally{buttons.forEach(b=>{b.disabled=false;b.textContent="Excluir"})}
}
function renderWorkouts(){const grid=document.getElementById("workoutGrid");grid.innerHTML=data.workouts.length?data.workouts.map(workoutCardHTML).join():'<div class="panel" style="grid-column:1/-1">'+emptyHTML("＋","Monte sua primeira ficha","Dê um nome ao treino e adicione seus exercícios.")+"</div>"}
function openWorkout(id){if(!getWorkout(id))return;selectedWorkoutId=id;document.getElementById("workoutGrid").classList.add("hidden");document.getElementById("createForm").classList.add("hidden");document.getElementById("workoutDetail").classList.remove("hidden");document.getElementById("exerciseFormBox").classList.add("hidden");renderExerciseList()}
function closeWorkoutDetail(){selectedWorkoutId=null;document.getElementById("workoutDetail").classList.add("hidden");document.getElementById("workoutGrid").classList.remove("hidden");renderWorkouts()}
function toggleExerciseForm(){const el=document.getElementById("exerciseFormBox");el.classList.toggle("hidden");if(!el.classList.contains("hidden"))document.getElementById("exerciseName").focus()}
document.getElementById("exerciseForm").addEventListener("submit",async e=>{e.preventDefault();const w=getWorkout(selectedWorkoutId);if(!w)return;const name=document.getElementById("exerciseName").value.trim(),muscle=document.getElementById("exerciseMuscle").value,sets=Number(document.getElementById("exerciseSets").value),reps=document.getElementById("exerciseReps").value.trim(),weight=Number(document.getElementById("exerciseWeight").value);if(!name||!reps||!Number.isInteger(sets)||sets<1||sets>20||!Number.isFinite(weight)||weight<0){alert("Confira os dados do exercício.");return}const videoUrl=document.getElementById("exerciseVideo").value.trim();w.exercises.push({id:uid(),name,muscle,sets,reps,weight,videoUrl});if(!await saveData()){w.exercises.pop();return}e.target.reset();document.getElementById("exerciseSets").value=3;document.getElementById("exerciseReps").value="10-12";document.getElementById("exerciseWeight").value=0;document.getElementById("exerciseVideo").value="";document.getElementById("exerciseFormBox").classList.add("hidden");renderExerciseList();renderHome()});
function renderExerciseList(){const w=getWorkout(selectedWorkoutId);if(!w)return;document.getElementById("detailName").textContent=w.name;document.getElementById("detailFocus").textContent=w.focus;document.getElementById("exerciseList").innerHTML=w.exercises.length?w.exercises.map((x,i)=>'<article class="exercise-row"><div class="exercise-row-main"><div class="exercise-name">'+(i+1)+'. '+esc(x.name)+'</div><div class="exercise-meta">'+esc(x.muscle)+(x.equipment?' · '+esc(x.equipment):'')+' · '+x.sets+' séries · '+esc(x.reps)+' repetições · '+x.weight+' kg</div></div><div class="exercise-actions"><button class="btn btn-outline btn-small" onclick="openExerciseTutorial(\''+x.id+'\')">▶ Tutorial</button><button class="btn btn-outline btn-small" onclick="editExercise(\''+x.id+'\')">Editar</button><button class="btn btn-danger btn-small" onclick="deleteExercise(\''+x.id+'\')">Excluir</button></div></article>').join(""):emptyHTML("＋","Nenhum exercício cadastrado","Use Adicionar exercício para escolher na biblioteca ou crie um exercício personalizado.")}
async function editExercise(id){
 const w=getWorkout(selectedWorkoutId),x=w?.exercises.find(e=>e.id===id);if(!x)return;
 const original={...x};
 const name=prompt("Nome do exercício:",x.name);if(name===null)return;if(!name.trim()){alert("O nome não pode ficar vazio.");return}
 const muscle=prompt("Grupo muscular:",x.muscle||"Corpo inteiro");if(muscle===null)return;if(!muscle.trim()){alert("Informe o grupo muscular.");return}
 const sets=Number(prompt("Número de séries (1 a 20):",x.sets));if(!Number.isInteger(sets)||sets<1||sets>20){alert("Informe de 1 a 20 séries.");return}
 const reps=prompt("Repetições por série:",x.reps);if(reps===null)return;if(!reps.trim()){alert("Informe as repetições.");return}
 const weight=Number(prompt("Carga em kg:",x.weight));if(!Number.isFinite(weight)||weight<0){alert("Informe uma carga válida.");return}
 const videoUrl=prompt("Link do vídeo tutorial (YouTube):",x.videoUrl||"");if(videoUrl===null)return;
 Object.assign(x,{name:name.trim(),muscle:muscle.trim(),sets,reps:reps.trim(),weight,videoUrl:videoUrl.trim()});
 if(await saveData()){renderExerciseList();renderHome();refreshShareOptions()}else Object.assign(x,original);
}
async function deleteExercise(id){
 const w=getWorkout(selectedWorkoutId),x=w?.exercises.find(e=>e.id===id);if(!w||!x||!confirm(`Excluir "${x.name}" desta ficha?`))return;
 const previous=[...w.exercises],next=previous.filter(item=>item.id!==id);
 const buttons=[...document.querySelectorAll(`button[onclick="deleteExercise('${id}')"]`)];
 buttons.forEach(b=>{b.disabled=true;b.textContent="Excluindo..."});
 try{
  saveQueue=saveQueue.catch(()=>{}).then(async()=>{
   if(!currentUser)throw new Error("Sua sessão expirou. Entre novamente.");
   const {data:updated,error}=await supabaseClient.from("workouts").update({exercises:next,updated_at:new Date().toISOString()}).eq("id",w.id).eq("user_id",currentUser.id).select("id");
   if(error)throw error;
   if(!updated?.length)throw new Error("O banco não confirmou a exclusão. Verifique as permissões da tabela workouts.");
  });
  await saveQueue;
  w.exercises=next;
  renderExerciseList();renderHome();refreshShareOptions();
 }catch(err){console.error("Erro ao excluir exercício:",err);alert("Não foi possível excluir o exercício: "+(err.message||"tente novamente"))}
 finally{buttons.forEach(b=>{b.disabled=false;b.textContent="Excluir"})}
}
function startWorkout(){const w=getWorkout(selectedWorkoutId);if(!w)return;if(!w.exercises.length){alert("Adicione pelo menos um exercício antes de iniciar.");return}if(!confirm(`Iniciar "${w.name}"?`))return;activeSession={workoutId:w.id,name:w.name,startedAt:new Date().toISOString(),exercises:w.exercises.map(x=>({name:x.name,muscle:x.muscle,sets:Array.from({length:x.sets},()=>({reps:x.reps,weight:x.weight,done:false}))}))};setView("session")}
function renderSession(){if(!activeSession)return;document.getElementById("sessionTitle").textContent=activeSession.name;document.getElementById("sessionExercises").innerHTML=activeSession.exercises.map((x,i)=>`<div class="panel exercise-session"><h3>${esc(x.name)}</h3><p class="exercise-meta">${esc(x.muscle)}</p><div class="session-set header"><span>SÉRIE</span><span>REPS</span><span>CARGA KG</span><span>OK</span></div>${x.sets.map((s,j)=>`<div class="session-set"><span>${j+1}</span><input aria-label="Repetições da série ${j+1}" value="${esc(s.reps)}" onchange="updateSessionSet(${i},${j},'reps',this.value)"><input aria-label="Carga da série ${j+1}" type="number" min="0" step=".5" value="${s.weight}" onchange="updateSessionSet(${i},${j},'weight',this.value)"><input class="check" aria-label="Marcar série concluída" type="checkbox" ${s.done?"checked":""} onchange="updateSessionSet(${i},${j},'done',this.checked)"></div>`).join("")}</div>`).join("")}
function updateSessionSet(i,j,key,value){const s=activeSession?.exercises[i]?.sets[j];if(!s)return;if(key==="weight"){const n=Number(value);if(!Number.isFinite(n)||n<0){alert("Informe uma carga válida.");renderSession();return}s.weight=n}else if(key==="reps"){if(!String(value).trim())return;s.reps=String(value).trim()}else s.done=Boolean(value)}
async function finishWorkout(){if(!activeSession)return;const sets=activeSession.exercises.flatMap(x=>x.sets),done=sets.filter(x=>x.done).length;if(!done&&!confirm("Nenhuma série foi marcada como concluída. Registrar mesmo assim?"))return;data.history.unshift({id:uid(),name:activeSession.name,startedAt:activeSession.startedAt,finishedAt:new Date().toISOString(),durationSeconds:Math.max(0,Math.round((Date.now()-new Date(activeSession.startedAt).getTime())/1000)),exercises:activeSession.exercises,totalSets:sets.length,completedSets:done});try{localStorage.setItem(historyKey(),JSON.stringify(data.history))}catch{}activeSession=null;alert(`Treino registrado! ${done} de ${sets.length} séries concluídas.`);renderProfile();setView("history")}
function cancelWorkout(){if(!activeSession||!confirm("Cancelar esta sessão? As marcações não serão salvas no histórico."))return;activeSession=null;setView("workouts")}
function formatDate(v){return new Date(v).toLocaleString("pt-BR",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"})}
function historyHTML(r){return `<div class="history-item"><div><strong>${esc(r.name)}</strong><p>${formatDate(r.finishedAt)} · ${r.exercises.length} exercícios</p><p>${r.completedSets} de ${r.totalSets} séries concluídas</p></div><span class="pill">Concluído</span></div>`}
function renderHistory(){const el=document.getElementById("historyList");el.innerHTML=data.history.length?data.history.map(historyHTML).join(""):emptyHTML("◷","Nenhum treino concluído","Quando você finalizar uma sessão, ela aparecerá nesta lista.")}

function renderProfile(){
 const h=data.history||[],secs=h.reduce((n,x)=>n+(x.durationSeconds||0),0);
 document.getElementById("profileSessions").textContent=h.length;
 document.getElementById("profileTime").textContent=secs?Math.round(secs/60)+" min":"—";
 document.getElementById("profileSets").textContent=h.reduce((n,x)=>n+(x.completedSets||0),0);
 const now=new Date(),first=new Date(now.getFullYear(),now.getMonth(),1),days=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();
 document.getElementById("calendarMonth").textContent=now.toLocaleDateString("pt-BR",{month:"long",year:"numeric"});
 const active=new Set(h.filter(x=>x.finishedAt&&new Date(x.finishedAt).getFullYear()===now.getFullYear()&&new Date(x.finishedAt).getMonth()===now.getMonth()).map(x=>new Date(x.finishedAt).getDate()));
 let cal=["D","S","T","Q","Q","S","S"].map(x=>'<span class="calendar-week">'+x+"</span>").join("");
 for(let i=0;i<first.getDay();i++)cal+='<span class="calendar-empty"></span>';
 for(let d=1;d<=days;d++)cal+='<span class="calendar-day '+(active.has(d)?"trained":"")+'">'+d+"</span>";
 document.getElementById("trainingCalendar").innerHTML=cal;
 const best={};h.slice().reverse().forEach(x=>(x.exercises||[]).forEach(ex=>(ex.sets||[]).forEach(s=>{const name=ex.name||"Exercício",weight=Number(s.weight)||0;if(!best[name]||weight>best[name].weight)best[name]={weight:weight,reps:s.reps||"—"}})));
 const rows=Object.entries(best);
 document.getElementById("progressList").innerHTML=rows.length?rows.map(([name,v])=>'<div class="history-item"><div><strong>'+esc(name)+'</strong><p>Maior carga registrada: '+v.weight+' '+(preferences.weightUnit||"kg")+' · Repetições: '+esc(v.reps)+'</p></div><span class="pill">Registrado</span></div>').join(""):emptyHTML("↗","Sem dados de evolução","Conclua sessões para registrar cargas e repetições.");
 document.getElementById("profileHistory").innerHTML=h.length?h.slice(0,8).map(historyHTML).join(""):emptyHTML("◷","Sem sessões","Seus treinos concluídos aparecerão aqui.");
}
function fillSettings(){const g=id=>document.getElementById(id);g("settingsName").value=preferences.name||currentUser?.user_metadata?.full_name||"";g("settingsBio").value=preferences.bio||"";g("settingsGenetics").value=preferences.genetics||"";g("settingsWeightUnit").value=preferences.weightUnit||"kg";g("settingsHeightUnit").value=preferences.heightUnit||"cm";g("settingsLanguage").value=preferences.language||"pt-BR";g("settingsTheme").value=preferences.theme||"light";renderAvatarPreview()}

function openAvatarLightbox(){
 const box=document.getElementById("avatarLightbox"),image=document.getElementById("avatarLightboxImage");
 if(!box||!image)return;
 const avatar=document.getElementById("profileAvatar"),photo=avatar?.querySelector("img");
 if(!photo){document.getElementById("avatarLightboxCaption").textContent="Você ainda não adicionou uma foto de perfil.";image.removeAttribute("src");image.classList.add("hidden")}
 else{image.src=photo.src;image.classList.remove("hidden");document.getElementById("avatarLightboxCaption").textContent=preferences.name||currentUser?.email||"Foto de perfil"}
 box.classList.remove("hidden");document.body.classList.add("avatar-lightbox-open");
}
function closeAvatarLightbox(){document.getElementById("avatarLightbox")?.classList.add("hidden");document.body.classList.remove("avatar-lightbox-open")}
