function renderAvatarPreview(){const preview=document.getElementById("settingsAvatarPreview");if(!preview)return;const name=preferences.name||currentUser?.user_metadata?.full_name||currentUser?.email||"HF";preview.innerHTML=preferences.avatar?'<img src="'+preferences.avatar+'" alt="Prévia da foto de perfil">':esc(name.trim().charAt(0).toUpperCase()||"HF")}
function applyPreferences(){document.body.classList.toggle("dark-theme",preferences.theme==="dark");const name=preferences.name||currentUser?.user_metadata?.full_name||currentUser?.email||"Minha conta",email=currentUser?.email||"",a=document.getElementById("profileAvatar"),n=document.getElementById("profileName"),e=document.getElementById("profileEmail");if(a)a.innerHTML=preferences.avatar?'<img src="'+preferences.avatar+'" alt="Foto de perfil">':esc(name.trim().charAt(0).toUpperCase()||"HF");if(n)n.textContent=name;if(e)e.textContent=email;document.documentElement.lang=preferences.language||"pt-BR";renderAvatarPreview()}
document.getElementById("settingsForm").addEventListener("submit",async e=>{e.preventDefault();preferences={...preferences,name:document.getElementById("settingsName").value.trim(),bio:document.getElementById("settingsBio").value.trim(),genetics:document.getElementById("settingsGenetics").value,weightUnit:document.getElementById("settingsWeightUnit").value,heightUnit:document.getElementById("settingsHeightUnit").value,language:document.getElementById("settingsLanguage").value,theme:document.getElementById("settingsTheme").value};try{localStorage.setItem(preferencesKey(),JSON.stringify(preferences))}catch{}applyPreferences();renderProfile();document.getElementById("settingsMessage").textContent="Configurações salvas neste dispositivo.";if(currentUser&&preferences.name){const r=await supabaseClient.auth.updateUser({data:{full_name:preferences.name}});if(r.error)document.getElementById("settingsMessage").textContent="Preferências salvas, mas não foi possível atualizar o nome da conta."}});
function refreshShareOptions(){const s=document.getElementById("shareWorkout");if(!s)return;const old=s.value;s.innerHTML='<option value="">Selecione uma ficha</option>'+data.workouts.map(w=>'<option value="'+esc(w.id)+'">'+esc(w.name)+"</option>").join("");if(data.workouts.some(w=>w.id===old))s.value=old}
function workoutSummary(){const w=getWorkout(document.getElementById("shareWorkout").value);if(!w){alert("Selecione uma ficha primeiro.");return""}return "Hyfolium — "+w.name+"\nFoco: "+w.focus+"\n\n"+w.exercises.map((x,i)=>(i+1)+". "+x.name+" — "+x.sets+" séries × "+x.reps+" repetições — "+x.weight+" "+(preferences.weightUnit||"kg")+" ("+x.muscle+")").join("\n")+"\n\nCompartilhado pelo Hyfolium."}
async function copyWorkoutSummary(){const text=workoutSummary();if(!text)return;try{await navigator.clipboard.writeText(text);const m=document.getElementById("shareMessage");m.textContent="Resumo copiado. Cole e envie ao seu personal.";m.classList.remove("hidden")}catch{prompt("Copie o resumo abaixo:",text)}}
function shareWorkoutWithTrainer(){const text=workoutSummary();if(!text)return;const email=document.getElementById("trainerEmail").value.trim();window.location.href="mailto:"+encodeURIComponent(email)+"?subject="+encodeURIComponent("Meu treino — Hyfolium")+"&body="+encodeURIComponent(text)}

document.getElementById("settingsAvatarFile").addEventListener("change",e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith("image/")){document.getElementById("avatarMessage").textContent="Escolha um arquivo de imagem.";return}if(file.size>12*1024*1024){document.getElementById("avatarMessage").textContent="A imagem deve ter no máximo 12 MB.";e.target.value="";return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const canvas=document.createElement("canvas"),max=320,scale=Math.min(1,max/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext("2d").drawImage(img,0,0,canvas.width,canvas.height);preferences.avatar=canvas.toDataURL("image/jpeg",.82);try{localStorage.setItem(preferencesKey(),JSON.stringify(preferences));document.getElementById("avatarMessage").textContent="Foto atualizada e salva neste dispositivo."}catch{document.getElementById("avatarMessage").textContent="A foto foi selecionada, mas não coube no armazenamento do navegador."}applyPreferences()};img.onerror=()=>document.getElementById("avatarMessage").textContent="Não foi possível abrir essa imagem.";img.src=reader.result};reader.readAsDataURL(file)});
document.getElementById("removeAvatarButton").addEventListener("click",()=>{preferences.avatar="";try{localStorage.setItem(preferencesKey(),JSON.stringify(preferences))}catch{}document.getElementById("settingsAvatarFile").value="";document.getElementById("avatarMessage").textContent="Foto removida.";applyPreferences()});

function youtubeEmbedUrl(value){const raw=String(value||"").trim();if(!raw)return "";try{const u=new URL(raw);let id="";if(u.hostname.includes("youtu.be"))id=u.pathname.split("/").filter(Boolean)[0]||"";else if(u.hostname.includes("youtube.com"))id=u.searchParams.get("v")||u.pathname.match(/\/(?:embed|shorts)\/([^/?]+)/)?.[1]||"";return id&&/^[\w-]{11}$/.test(id)?"https://www.youtube-nocookie.com/embed/"+id+"?rel=0":""}catch{return ""}}
function openExerciseTutorial(id){const w=getWorkout(selectedWorkoutId),x=w?.exercises.find(e=>e.id===id);if(!x)return;showExerciseGuide({name:x.name,muscle:x.muscle,equipment:x.equipment,instructions:x.instructions||"Mantenha o movimento controlado e use uma amplitude confortável.",videoUrl:x.videoUrl,videoSearchUrl:x.videoSearchUrl||"https://www.youtube.com/results?search_query="+encodeURIComponent(x.name+" execução correta tutorial")})}
function closeExerciseTutorial(){document.getElementById("exerciseTutorialModal")?.classList.add("hidden");document.getElementById("tutorialVideoWrap").innerHTML="";document.body.classList.remove("tutorial-open")}
document.getElementById("exerciseTutorialModal").addEventListener("click",e=>{if(e.target.id==="exerciseTutorialModal")closeExerciseTutorial()});
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeExerciseTutorial()});


const exerciseCatalog=[["Supino reto com barra","Peito","Barra","🏋️","Deite com os pés firmes no chão. Segure a barra um pouco além da largura dos ombros, desça com controle até próximo ao peito e empurre sem perder a estabilidade."],["Supino inclinado com halteres","Peito","Halteres","🏋️","Ajuste o banco em uma inclinação moderada. Mantenha os pés apoiados, desça os halteres ao lado do peito e empurre para cima sem bater os pesos."],["Crucifixo na máquina","Peito","Máquina","⚙️","Ajuste o banco para que os braços fiquem alinhados ao peito. Una os apoios à frente sem impulso e retorne lentamente, mantendo os cotovelos levemente flexionados."],["Crossover na polia","Peito","Polia / Cabo","〰️","Fique no centro das polias, com um pé à frente. Traga as mãos em arco à frente do tronco e retorne devagar, sem deixar os ombros avançarem."],["Flexão de braços","Peito","Peso corporal","🤸","Apoie mãos e pés no chão, mantendo o corpo alinhado. Flexione os cotovelos para aproximar o peito do chão e empurre o solo para voltar."],["Puxada alta pela frente","Costas","Polia / Cabo","〰️","Sente-se com as coxas apoiadas. Puxe a barra em direção à parte alta do peito, levando os cotovelos para baixo, e retorne com controle."],["Remada baixa com triângulo","Costas","Polia / Cabo","〰️","Sente-se com a coluna neutra e joelhos levemente flexionados. Puxe o triângulo em direção ao abdômen e estenda os braços sem arredondar as costas."],["Remada cavalinho","Costas","Barra","🏋️","Posicione os pés firmes e incline o tronco mantendo a coluna neutra. Puxe a barra em direção ao abdômen e desça lentamente."],["Remada unilateral com halter","Costas","Halteres","🏋️","Apoie uma mão e um joelho no banco. Puxe o halter em direção ao quadril sem girar o tronco e abaixe com controle."],["Pulldown com braços estendidos","Costas","Polia / Cabo","〰️","Fique de frente para a polia com braços quase estendidos. Puxe a barra até as coxas mantendo o tronco estável e retorne devagar."],["Desenvolvimento com halteres","Ombros","Halteres","🏋️","Sente-se com as costas apoiadas. Comece com os halteres na altura dos ombros e empurre para cima sem arquear excessivamente a lombar."],["Elevação lateral","Ombros","Halteres","🏋️","Com os braços ao lado do corpo e cotovelos levemente flexionados, eleve os halteres até próximo da altura dos ombros e desça devagar."],["Crucifixo inverso na máquina","Ombros","Máquina","⚙️","Ajuste o banco e segure os apoios à frente. Abra os braços para os lados sem encolher os ombros e retorne lentamente."],["Rosca direta","Bíceps","Barra","🏋️","Fique em pé com os cotovelos próximos ao tronco. Flexione os braços para subir a barra e desça sem balançar o corpo."],["Rosca martelo","Bíceps","Halteres","🏋️","Segure os halteres com as palmas voltadas uma para a outra. Flexione os cotovelos mantendo os punhos neutros e retorne com controle."],["Rosca Scott","Bíceps","Máquina","⚙️","Apoie a parte posterior dos braços no banco Scott. Flexione os cotovelos sem tirar os braços do apoio e desça sem travar bruscamente."],["Tríceps na polia com corda","Tríceps","Polia / Cabo","〰️","Mantenha os cotovelos junto ao corpo. Estenda os braços para baixo, separando levemente as pontas da corda, e retorne sem mover os ombros."],["Tríceps francês com halter","Tríceps","Halteres","🏋️","Segure um halter acima da cabeça. Flexione os cotovelos para baixar o peso atrás da cabeça e estenda os braços mantendo os cotovelos apontados para cima."],["Agachamento","Pernas","Peso corporal","🦵","Afaste os pés aproximadamente na largura dos ombros. Leve o quadril para trás e para baixo, mantendo os pés apoiados e os joelhos acompanhando a direção dos pés."],["Leg press","Pernas","Máquina","⚙️","Ajuste o encosto e posicione os pés na plataforma. Desça até uma amplitude confortável sem tirar o quadril do encosto e empurre sem travar os joelhos."],["Cadeira extensora","Pernas","Máquina","⚙️","Ajuste o eixo da máquina próximo ao joelho. Estenda as pernas de forma controlada e retorne sem deixar a carga despencar."],["Mesa flexora","Pernas","Máquina","⚙️","Ajuste o apoio próximo aos tornozelos. Flexione os joelhos para aproximar os calcanhares e retorne lentamente."],["Hip thrust","Glúteos","Barra","🏋️","Apoie a parte superior das costas em um banco e mantenha os pés firmes. Eleve o quadril até alinhar tronco e coxas, contraindo os glúteos, sem hiperestender a lombar."],["Panturrilha em pé","Panturrilhas","Máquina","⚙️","Apoie a parte da frente dos pés na plataforma. Eleve os calcanhares, faça uma pausa breve e desça com controle."],["Prancha abdominal","Abdômen","Peso corporal","🤸","Apoie antebraços e pontas dos pés. Mantenha cabeça, tronco e quadril alinhados, contraindo o abdômen e respirando normalmente."],["Caminhada na esteira","Cardio","Esteira","🏃","Escolha uma velocidade confortável, mantenha postura natural e use o apoio lateral apenas para entrar e sair da esteira com segurança."]].map(([name,muscle,equipment,icon,instructions])=>({name,muscle,equipment,icon,instructions}));
function openExerciseLibrary(){if(!getWorkout(selectedWorkoutId)){alert("Abra uma ficha antes de adicionar exercícios.");return}document.getElementById("exerciseLibraryModal").classList.remove("hidden");document.body.classList.add("library-open");renderExerciseCatalog();document.getElementById("librarySearch").focus()}
function closeExerciseLibrary(){document.getElementById("exerciseLibraryModal")?.classList.add("hidden");document.body.classList.remove("library-open")}
function renderExerciseCatalog(){const q=(document.getElementById("librarySearch").value||"").trim().toLocaleLowerCase("pt-BR"),m=document.getElementById("libraryMuscle").value,e=document.getElementById("libraryEquipment").value;const list=exerciseCatalog.filter(x=>(!q||(x.name+" "+x.muscle+" "+x.equipment).toLocaleLowerCase("pt-BR").includes(q))&&(!m||x.muscle===m)&&(!e||x.equipment===e));document.getElementById("libraryResultCount").textContent=list.length+" exercício(s) encontrado(s)";document.getElementById("exerciseLibraryList").innerHTML=list.length?list.map(x=>'<article class="library-exercise-card"><div class="library-exercise-art" aria-hidden="true"><span>'+x.icon+'</span></div><div class="library-exercise-info"><strong>'+esc(x.name)+'</strong><span>'+esc(x.muscle)+' · '+esc(x.equipment)+'</span><button type="button" class="library-tutorial-link" onclick="previewCatalogExercise('+exerciseCatalog.indexOf(x)+')">▶ Ver execução e vídeo</button></div><button type="button" class="btn btn-primary btn-small" onclick="addCatalogExercise('+exerciseCatalog.indexOf(x)+')">Adicionar</button></article>').join(""):emptyHTML("⌕","Nenhum exercício encontrado","Tente outro nome ou altere os filtros.")}
function addCatalogExercise(index){const x=exerciseCatalog[index],w=getWorkout(selectedWorkoutId);if(!x||!w)return;w.exercises.push({id:uid(),name:x.name,muscle:x.muscle,equipment:x.equipment,sets:3,reps:"10-12",weight:0,instructions:x.instructions,videoSearchUrl:"https://www.youtube.com/results?search_query="+encodeURIComponent(x.name+" execução correta tutorial")});saveData().then(saved=>{if(saved){renderExerciseList();renderHome();closeExerciseLibrary()}else w.exercises.pop()})}
function previewCatalogExercise(index){const x=exerciseCatalog[index];if(!x)return;showExerciseGuide({name:x.name,muscle:x.muscle,equipment:x.equipment,instructions:x.instructions,videoSearchUrl:"https://www.youtube.com/results?search_query="+encodeURIComponent(x.name+" execução correta tutorial")})}
function showExerciseGuide(x){const modal=document.getElementById("exerciseTutorialModal"),wrap=document.getElementById("tutorialVideoWrap"),hint=document.getElementById("tutorialHint"),link=document.getElementById("tutorialSearchLink");document.getElementById("tutorialTitle").textContent=x.name;const embed=youtubeEmbedUrl(x.videoUrl);if(embed){wrap.innerHTML='<iframe src="'+embed+'" title="Tutorial de '+esc(x.name)+'" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen loading="lazy"></iframe>'}else{wrap.innerHTML='<div class="tutorial-empty"><span>▶</span><strong>Vídeo demonstrativo</strong><p>Abra a busca direcionada para assistir à demonstração deste exercício.</p></div>'}hint.textContent=(x.muscle||"")+(x.equipment?" · "+x.equipment:"")+" — "+(x.instructions||"Confira a demonstração antes de executar.");link.href=x.videoSearchUrl||"https://www.youtube.com/results?search_query="+encodeURIComponent(x.name+" execução correta");link.textContent="Assistir vídeo no YouTube";modal.classList.remove("hidden");document.body.classList.add("tutorial-open")}
document.getElementById("librarySearch").addEventListener("input",renderExerciseCatalog);
document.getElementById("libraryMuscle").addEventListener("change",renderExerciseCatalog);
document.getElementById("libraryEquipment").addEventListener("change",renderExerciseCatalog);
document.getElementById("exerciseLibraryModal").addEventListener("click",e=>{if(e.target.id==="exerciseLibraryModal")closeExerciseLibrary()});

/* Feed social: publicações de fotos e vídeos */
let selectedPostFile=null,postPreviewUrl=null,feedLoadToken=0;
const postBucket="feed-media";
function openCreatePost(){if(!currentUser){showAuthMessage("Entre na sua conta para publicar.",true);return}document.getElementById("createPostModal").classList.remove("hidden");document.body.classList.add("post-modal-open")}
function closeCreatePost(){stopLiveCamera();document.getElementById("createPostModal").classList.add("hidden");document.body.classList.remove("post-modal-open")}
function resetPostSelection(){selectedPostFile=null;if(postPreviewUrl){URL.revokeObjectURL(postPreviewUrl);postPreviewUrl=null}const p=document.getElementById("postMediaPreview");p.innerHTML="";p.classList.add("hidden");document.getElementById("postCameraInput").value="";document.getElementById("postMediaInput").value=""}
function choosePostFile(file){if(!file)return;const allowed=/^(image\/(jpeg|png|webp|gif)|video\/(mp4|webm|quicktime))$/i;if(!allowed.test(file.type)){document.getElementById("postUploadMessage").textContent="Formato não suportado. Use JPG, PNG, WEBP, GIF, MP4, WEBM ou MOV.";return}if(file.size>100*1024*1024){document.getElementById("postUploadMessage").textContent="O arquivo ultrapassa o limite de 100 MB.";return}resetPostSelection();selectedPostFile=file;postPreviewUrl=URL.createObjectURL(file);const preview=document.getElementById("postMediaPreview");if(file.type.startsWith("video/")){const v=document.createElement("video");v.src=postPreviewUrl;v.controls=true;v.playsInline=true;preview.appendChild(v)}else{const img=document.createElement("img");img.src=postPreviewUrl;img.alt="Prévia da publicação";preview.appendChild(img)}preview.classList.remove("hidden");document.getElementById("postUploadMessage").textContent=file.name}
async function loadFeedPosts(){const container=document.getElementById("feedPosts");if(!container||!currentUser)return;const token=++feedLoadToken;container.innerHTML='<div class="feed-loading">Carregando publicações...</div>';try{const {data:posts,error}=await withTimeout(supabaseClient.from("feed_posts").select("id,user_id,user_name,media_url,media_type,caption,created_at").order("created_at",{ascending:false}).limit(50),12000,"O feed demorou para responder.");if(error)throw error;if(token!==feedLoadToken)return;if(!posts?.length){container.innerHTML='<div class="feed-empty"><span>▧</span><strong>O feed ainda está vazio</strong><p>Seja a primeira pessoa a compartilhar uma foto ou vídeo do treino.</p></div>';return}container.innerHTML=posts.map(post=>{const name=esc(post.user_name||"Usuário"),date=new Date(post.created_at).toLocaleString("pt-BR",{dateStyle:"medium",timeStyle:"short"}),media=post.media_type==="video"?'<video class="feed-media" src="'+esc(post.media_url)+'" controls playsinline preload="metadata"></video>':'<img class="feed-media" src="'+esc(post.media_url)+'" alt="Publicação de '+name+'" loading="lazy">';return '<article class="feed-post"><header class="feed-post-head"><div class="feed-post-avatar">'+name.trim().charAt(0).toUpperCase()+'</div><div class="feed-post-author"><strong>'+name+'</strong><small>'+esc(date)+'</small></div>'+(post.user_id===currentUser.id?'<button type="button" class="feed-delete" data-delete-post="'+esc(post.id)+'">Excluir</button>':"")+'</header>'+media+(post.caption?'<p class="feed-caption">'+esc(post.caption)+'</p>':"")+'</article>'}).join("");container.querySelectorAll("[data-delete-post]").forEach(btn=>btn.addEventListener("click",()=>deleteFeedPost(btn.dataset.deletePost,btn)))}catch(err){console.error("Erro ao carregar feed:",err);if(token===feedLoadToken)container.innerHTML='<div class="feed-empty"><strong>Não foi possível carregar o feed.</strong><p>'+esc(err.message||"Tente atualizar a página.")+'</p></div>'}}
async function deleteFeedPost(id,button){if(!confirm("Excluir esta publicação?"))return;button.disabled=true;try{const {data:post,error:findError}=await supabaseClient.from("feed_posts").select("id,user_id,media_url").eq("id",id).eq("user_id",currentUser.id).single();if(findError)throw findError;const path=decodeURIComponent(new URL(post.media_url).pathname.split("/storage/v1/object/public/"+postBucket+"/")[1]||"");const {error}=await supabaseClient.from("feed_posts").delete().eq("id",id).eq("user_id",currentUser.id);if(error)throw error;if(path)await supabaseClient.storage.from(postBucket).remove([path]);await loadFeedPosts()}catch(err){console.error(err);alert("Não foi possível excluir: "+(err.message||"tente novamente"));button.disabled=false}}
document.getElementById("createPostFab").addEventListener("click",openCreatePost);document.getElementById("closePostModal").addEventListener("click",closeCreatePost);document.querySelectorAll("[data-close-post]").forEach(el=>el.addEventListener("click",closeCreatePost));
let liveCameraStream=null;
async function stopLiveCamera(){if(liveCameraStream){liveCameraStream.getTracks().forEach(track=>track.stop());liveCameraStream=null}const video=document.getElementById("liveCameraVideo");if(video)video.srcObject=null;document.getElementById("liveCameraPanel").classList.add("hidden")}
async function startLiveCamera(){const message=document.getElementById("postUploadMessage");if(!navigator.mediaDevices?.getUserMedia){message.textContent="Câmera ao vivo indisponível neste navegador. Abrindo a câmera do dispositivo…";document.getElementById("postCameraInput").click();return}try{await stopLiveCamera();liveCameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}},audio:false});const video=document.getElementById("liveCameraVideo");video.srcObject=liveCameraStream;document.getElementById("liveCameraPanel").classList.remove("hidden");message.textContent="Câmera ativa. Toque em Capturar foto."}catch(err){console.warn("Não foi possível iniciar câmera ao vivo:",err);message.textContent="Não foi possível abrir a câmera ao vivo. Vou abrir a opção de câmera do celular.";document.getElementById("postCameraInput").click()}}
document.getElementById("takePhotoButton").addEventListener("click",startLiveCamera);
document.getElementById("closeLiveCamera").addEventListener("click",stopLiveCamera);
document.getElementById("captureLivePhoto").addEventListener("click",()=>{const video=document.getElementById("liveCameraVideo");if(!video.videoWidth||!video.videoHeight){document.getElementById("postUploadMessage").textContent="A câmera ainda está carregando. Tente novamente em um instante.";return}const canvas=document.createElement("canvas");canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext("2d").drawImage(video,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{if(!blob){document.getElementById("postUploadMessage").textContent="Não foi possível capturar a foto. Tente novamente.";return}choosePostFile(new File([blob],"hyfolium-"+Date.now()+".jpg",{type:"image/jpeg"}));stopLiveCamera()},"image/jpeg",.92)});
document.getElementById("chooseMediaButton").addEventListener("click",()=>document.getElementById("postMediaInput").click());document.getElementById("postCameraInput").addEventListener("change",e=>choosePostFile(e.target.files?.[0]));document.getElementById("postMediaInput").addEventListener("change",e=>choosePostFile(e.target.files?.[0]));
document.getElementById("createPostForm").addEventListener("submit",async e=>{e.preventDefault();const message=document.getElementById("postUploadMessage"),button=document.getElementById("publishPostButton");if(!currentUser){message.textContent="Entre na sua conta para publicar.";return}if(!selectedPostFile){message.textContent="Tire uma foto ou escolha uma imagem/vídeo primeiro.";return}button.disabled=true;button.textContent="Enviando mídia…";message.textContent="Enviando sua publicação. Não feche esta janela.";let uploadedPath=null;try{const file=selectedPostFile,ext=(file.name.split(".").pop()||(file.type.startsWith("video/")?"mp4":"jpg")).toLowerCase().replace(/[^a-z0-9]/g,""),path=currentUser.id+"/"+uid()+"."+ext;uploadedPath=path;const {error:uploadError}=await withTimeout(supabaseClient.storage.from(postBucket).upload(path,file,{contentType:file.type,upsert:false,cacheControl:"3600"}),60000,"O envio demorou demais. Tente com um arquivo menor ou verifique sua conexão.");if(uploadError)throw uploadError;const {data:publicData}=supabaseClient.storage.from(postBucket).getPublicUrl(path);const userName=preferences.name||currentUser.user_metadata?.full_name||currentUser.email?.split("@")[0]||"Usuário";const {error:insertError}=await supabaseClient.from("feed_posts").insert({user_id:currentUser.id,user_name:userName,media_url:publicData.publicUrl,media_type:file.type.startsWith("video/")?"video":"image",caption:document.getElementById("postCaption").value.trim()});if(insertError)throw insertError;document.getElementById("postCaption").value="";resetPostSelection();message.textContent="Publicado com sucesso!";await loadFeedPosts();setTimeout(closeCreatePost,450)}catch(err){console.error("Erro ao publicar:",err);if(uploadedPath)await supabaseClient.storage.from(postBucket).remove([uploadedPath]);message.textContent="Não foi possível publicar: "+(err.message||"tente novamente")}finally{button.disabled=false;button.textContent="Publicar no feed"}});
